// src/utils/sdk-client.ts
var createDataFabricClient = async (tenantOverride) => {
  const status = await getLoginStatusAsync();
  if (status.loginStatus !== "Logged in" || !status.accessToken || !status.baseUrl) {
    throw new Error(status.hint ?? "Not logged in. Run 'uip login' first.");
  }
  return new UiPath2({
    secret: status.accessToken,
    baseUrl: status.baseUrl,
    orgName: status.organizationName,
    tenantName: tenantOverride ?? status.tenantName
  });
};
var connectOrFail = async (tenantOverride) => {
  const [clientError, sdk] = await catchError(createDataFabricClient(tenantOverride));
  if (clientError) {
    fail("Error connecting to Data Fabric", await extractErrorMessage(clientError));
    return;
  }
  return sdk;
};

