// src/utils/input.ts
init_src();
var STDIN_SENTINEL = "-";
async function readFileBinary(filePath) {
  const fs7 = getFileSystem();
  const content = await fs7.readFile(filePath);
  if (content === null) {
    throw new Error(`Could not read file: ${filePath}`);
  }
  return content;
}
async function readJsonInput(filePath, inline, missingMsg = "Provide either --file <path> or inline data.") {
  if (!filePath && !inline) {
    throw new Error(missingMsg);
  }
  if (inline === STDIN_SENTINEL || filePath === STDIN_SENTINEL) {
    const stdinData = await readStdin();
    if (stdinData === null) {
      throw new Error("Expected JSON on stdin but got none. Pipe data in, e.g. `... --body - < payload.json`.");
    }
    return parseJson(stdinData);
  }
  let raw;
  if (filePath) {
    const fs7 = getFileSystem();
    const content = await fs7.readFile(filePath, "utf-8");
    if (content === null) {
      throw new Error(`Could not read file: ${filePath}`);
    }
    raw = content;
  } else {
    raw = inline;
  }
  return parseJson(raw);
}
function parseJson(raw) {
  try {
    return JSON.parse(raw);
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err);
    const hint = process.platform === "win32" ? " On Windows cmd/PowerShell, characters like & | < > ^ split the command — use `--file <path>` or pipe JSON via `--body -`." : "";
    throw new Error(`Invalid JSON input: ${detail}.${hint}`);
  }
}

